def _char(id: str, name: str, category: str, description: str, *, traits: tuple[str, ...], age: str, build: str, hair: str, wardrobe: str, tone: str, pace: str, dialect: str = "Egyptian Arabic", humor: str = "", behavior: tuple[str, ...] = ()) -> CharacterProfile:
    now = _now()
    return CharacterProfile(id=id, project_id=LIBRARY_PROJECT_ID, name=name, description=description,
        personality={"traits":list(traits)}, appearance={"age":age,"build":build,"hair":hair,"wardrobe":wardrobe},
        voice={"tone":tone,"pace":pace}, speaking_style={"dialect":dialect,"humor":humor},
        visual_style={"detail":"cinematic character consistency","identity":"stable across shots"},
        behavior_rules=behavior or ("keep face, body and wardrobe identity stable","do not change personality without explicit instruction"),
        reference_asset_ids=(), provider_character_id=None, metadata={"library":"default-egypt","category":category,"ready":True}, version=1, created_at=now, updated_at=now)


